#!/usr/bin/env python3
# V1.1 TEST ONLY source-verified installer, SHA256 of decompressed source:
# af5bd4746820cabd86e483e74e7544bf479150a24f84b722f33259d242a47255
# Compressed for CI transport; see source manifest + applied diff artifact.
import hashlib, base64, zlib
payload=""
source=zlib.decompress(base64.b64decode(payload))
assert hashlib.sha256(source).hexdigest()=="af5bd4746820cabd86e483e74e7544bf479150a24f84b722f33259d242a47255"
# V1.5 safety: non-persistent test controls; no wolfconfig contamination.
assert source.count(b'CVAR_ARCHIVE') == 4
source=source.replace(b'CVAR_ARCHIVE',b'CVAR_TEMP')
exec(compile(source.decode("utf-8"),"apply_v11_unpacked.py","exec"))
